import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import { AlertTriangle, Archive, ArrowDownLeft, ArrowDownUp, ArrowUpRight, Banknote, Boxes, Check, ChevronDown, CirclePlus, FileText, KeyRound, Package, Printer, RefreshCw, Search, ShieldCheck, ShoppingBag, ShoppingCart, Truck, Undo2, UsersRound, Wallet, X } from "lucide-react";
import { dateOnly, dateTime, get, money, patch, post, put, type CashSession, type Category, type Contact, type CustomerDetail, type Product, type ProfitReport, type Purchase, type Sale, type SaleReturn, type ShopSettings, type SupplierDetail, type User } from "../lib/api";
import type { PageId } from "./Shell";

type Notify = (message: string, kind?: "success" | "error") => void;
export function Modal({ title, onClose, children, wide = false }: { title: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className={`modal ${wide ? "modal-wide" : ""}`}><header className="modal-head"><div><h2>{title}</h2><span>اطلاعات در همین دستگاه ذخیره می‌شود</span></div><button className="icon-button" onClick={onClose}><X size={19}/></button></header>{children}</section></div>;
}
function Loading() { return <div className="loading"><RefreshCw size={18}/> در حال بارگذاری اطلاعات…</div>; }
function ErrorBox({ message }: { message: string }) { return <div className="error-box"><AlertTriangle size={17}/>{message}</div>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className="empty"><div><Package size={22}/></div><b>{title}</b><span>{text}</span></div>; }
function SectionHead({ title, subtitle, action }: { title: string; subtitle?: string; action?: ReactNode }) { return <div className="section-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>; }
function Field({ label, children, full = false }: { label: string; children: ReactNode; full?: boolean }) { return <label className={`field ${full ? "full" : ""}`}><span>{label}</span>{children}</label>; }
const numberValue = (event: React.ChangeEvent<HTMLInputElement>) => Number(event.currentTarget.value || 0);

type Summary = { todaySales: number; todayCount: number; todayPurchases: number; todayReturns: number; creditOutstanding: number; stockValue: number; productCount: number; lowStockCount: number; lowStock: Product[]; recentSales: Sale[] };
export function DashboardPage({ onNavigate }: { onNavigate: (page: PageId) => void }) {
  const [data, setData] = useState<Summary | null>(null);
  const [error, setError] = useState("");
  useEffect(() => { get<Summary>("/dashboard/summary").then(setData).catch((e) => setError(e.message)); }, []);
  if (!data && !error) return <Loading/>;
  return <div className="page-stack">
    {error && <ErrorBox message={error}/>}
    <div className="welcome-row"><div><div className="eyebrow">{new Intl.DateTimeFormat("fa-AF", { dateStyle: "full" }).format(new Date())}</div><h2>به فروشگاه‌تان خوش آمدید</h2><p>وضعیت فروش و موجودی امروز را از همین‌جا ببینید.</p></div><button className="primary-button" onClick={() => onNavigate("pos")}><ShoppingCart size={18}/> آغاز فروش</button></div>
    <div className="metric-grid">
      <Metric icon={Banknote} label="فروش امروز" value={money(data?.todaySales ?? 0)} note={`${data?.todayCount ?? 0} فاکتور ثبت‌شده`} tone="green"/>
      <Metric icon={Undo2} label="برگشتی امروز" value={money(data?.todayReturns ?? 0)} note="بازپرداخت به مشتریان" tone="amber"/>
      <Metric icon={Truck} label="خرید امروز" value={money(data?.todayPurchases ?? 0)} note="ورود کالا به انبار" tone="violet"/>
      <Metric icon={Wallet} label="بدهی نسیه (کل)" value={money(data?.creditOutstanding ?? 0)} note="ماندهٔ همهٔ مشتریان" tone={data && data.creditOutstanding > 0 ? "amber" : "green"}/>
      <Metric icon={Package} label="ارزش انبار" value={money(data?.stockValue ?? 0)} note="به قیمت خرید" tone="blue"/>
      <Metric icon={Boxes} label="کالاهای فعال" value={String(data?.productCount ?? 0)} note="در فهرست فروش" tone="violet"/>
      <Metric icon={AlertTriangle} label="کالاهای کم‌موجود" value={String(data?.lowStockCount ?? 0)} note="نیازمند بررسی" tone="amber"/>
      <Metric icon={FileText} label="فاکتورهای امروز" value={String(data?.todayCount ?? 0)} note="فروش‌های ثبت‌شده" tone="blue"/>
    </div>
    <div className="dashboard-grid"><section className="surface"><SectionHead title="فروش‌های تازه" subtitle="آخرین فاکتورهای ثبت‌شده" action={<button className="text-button" onClick={() => onNavigate("sales")}>مشاهده همه</button>}/>{data?.recentSales.length ? <div className="table-wrap"><table><thead><tr><th>شماره فاکتور</th><th>مشتری</th><th>مبلغ</th><th>زمان</th><th></th></tr></thead><tbody>{data.recentSales.map((sale) => <tr key={sale.id}><td className="mono">{sale.receiptNo}</td><td>{sale.customer?.name || "مشتری گذری"}</td><td className="strong">{money(sale.total)}</td><td className="muted">{dateTime(sale.createdAt)}</td><td><span className="status-pill paid"><Check size={13}/> ثبت شد</span></td></tr>)}</tbody></table></div> : <Empty title="هنوز فروشی ثبت نشده" text="با ثبت اولین فروش، خلاصه آن در این بخش دیده می‌شود."/>}</section>
      <section className="surface"><SectionHead title="هشدار موجودی" subtitle="کالاهایی که به حداقل موجودی رسیده‌اند" action={<button className="icon-button" onClick={() => onNavigate("inventory")}><ChevronDown size={18}/></button>}/>{data?.lowStock.length ? <div className="stock-alert-list">{data.lowStock.map((product) => <div className="stock-alert" key={product.id}><div className="product-initial">{product.name.slice(0, 1)}</div><div className="grow"><b>{product.name}</b><span>{product.sku}</span></div><strong className="stock-low">{product.stock} <small>{product.unit}</small></strong></div>)}</div> : <Empty title="موجودی مناسب است" text="فعلاً کالای کم‌موجودی ندارید."/>}</section></div>
    <section className="quick-actions"><div><span className="eyebrow">دسترسی سریع</span><h3>کارهای روزانه</h3></div><button onClick={() => onNavigate("pos")}><ShoppingCart/><span><b>ثبت فروش</b><small>فاکتور جدید بسازید</small></span></button><button onClick={() => onNavigate("products")}><CirclePlus/><span><b>افزودن کالا</b><small>کالای تازه به فهرست</small></span></button><button onClick={() => onNavigate("cash")}><Banknote/><span><b>وضعیت صندوق</b><small>باز و بسته کردن صندوق</small></span></button><button onClick={() => onNavigate("customers")}><UsersRound/><span><b>افزودن مشتری</b><small>مدیریت مشتریان</small></span></button></section>
  </div>;
}
function Metric({ icon: Icon, label, value, note, tone }: { icon: typeof Banknote; label: string; value: string; note: string; tone: string }) { return <article className="metric-card"><div className={`metric-icon ${tone}`}><Icon size={20}/></div><span className="metric-label">{label}</span><strong>{value}</strong><small>{note}</small></article>; }

type ProductForm = { sku: string; barcode: string; name: string; unit: string; price: number; cost: number; stock: number; minStock: number; categoryId: string };
const blankProduct: ProductForm = { sku: "", barcode: "", name: "", unit: "عدد", price: 0, cost: 0, stock: 0, minStock: 0, categoryId: "" };
export function ProductsPage({ notify }: { notify: Notify }) {
  const [products, setProducts] = useState<Product[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [query, setQuery] = useState(""); const [edit, setEdit] = useState<Product | null | false>(false); const [form, setForm] = useState<ProductForm>(blankProduct); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const [archived, setArchived] = useState(false);
  const load = (showArchived = archived) => Promise.all([get<Product[]>(showArchived ? "/products?archived=1" : "/products"), get<Category[]>("/categories")]).then(([p, c]) => { setProducts(p); setCategories(c); }).catch((e) => setError(e.message));
  useEffect(() => { void load(archived); }, [archived]);
  const shown = products.filter((p) => `${p.name} ${p.sku} ${p.barcode || ""}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()));
  const openNew = () => { setForm(blankProduct); setEdit(null); };
  const openEdit = (product: Product) => { setForm({ sku: product.sku, barcode: product.barcode || "", name: product.name, unit: product.unit, price: product.price, cost: product.cost, stock: product.stock, minStock: product.minStock, categoryId: product.categoryId || "" }); setEdit(product); };
  const save = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { const body = { ...form, barcode: form.barcode || undefined, categoryId: form.categoryId || undefined }; if (edit) await patch(`/products/${edit.id}`, body); else await post("/products", body); notify(edit ? "کالا ویرایش شد." : "کالا ثبت شد."); setEdit(false); await load(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  const archive = async (product: Product) => { if (!window.confirm(`کالای «${product.name}» از فهرست فروش پنهان شود؟`)) return; try { await patch(`/products/${product.id}/archive`, {}); notify("کالا بایگانی شد."); await load(); } catch (e) { notify((e as Error).message, "error"); } };
  const restore = async (product: Product) => { try { await patch(`/products/${product.id}/restore`, {}); notify("کالا به فهرست فروش بازگشت."); await load(); } catch (e) { notify((e as Error).message, "error"); } };
  return <div className="page-stack"><section className="surface"><SectionHead title="فهرست کالاها" subtitle={`${products.length} کالا ${archived ? "بایگانی‌شده" : "فعال"} در سیستم ثبت شده است`} action={<div className="row-actions"><button className="secondary-button" onClick={() => setArchived((value) => !value)}><Archive size={16}/> {archived ? "بازگشت به کالاهای فعال" : "بایگانی‌شده‌ها"}</button><button className="primary-button" onClick={openNew}><CirclePlus size={18}/> کالای جدید</button></div>}/><div className="toolbar"><div className="search-box"><Search size={17}/><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="جست‌وجوی نام، بارکد یا کد کالا…"/></div><span className="toolbar-count">{shown.length} مورد</span></div>{error && <ErrorBox message={error}/>}<div className="table-wrap"><table><thead><tr><th>کالا</th><th>کد کالا</th><th>دسته‌بندی</th><th>قیمت فروش</th><th>موجودی</th><th>وضعیت</th><th></th></tr></thead><tbody>{shown.map((p) => <tr key={p.id}><td><div className="cell-main"><span className="product-initial">{p.name.slice(0, 1)}</span><div><b>{p.name}</b><small>{p.barcode || p.unit}</small></div></div></td><td className="mono">{p.sku}</td><td><span className="category-label">{p.category?.name || "بدون دسته"}</span></td><td className="strong">{money(p.price)}</td><td><b className={p.stock <= p.minStock ? "stock-low" : ""}>{p.stock}</b> <small className="muted">{p.unit}</small></td><td><span className={`status-pill ${archived ? "neutral" : p.stock <= p.minStock ? "warning" : "paid"}`}>{archived ? "بایگانی" : p.stock <= p.minStock ? "کم‌موجود" : "موجود"}</span></td><td><div className="row-actions">{archived ? <button className="text-button" onClick={() => void restore(p)}><Undo2 size={14}/> بازگردانی</button> : <><button className="text-button" onClick={() => openEdit(p)}>ویرایش</button><button className="text-button danger-text" onClick={() => void archive(p)}>بایگانی</button></>}</div></td></tr>)}</tbody></table>{!shown.length && <Empty title={archived ? "کالای بایگانی‌شده نیست" : "کالایی پیدا نشد"} text={archived ? "کالاهای بایگانی‌شده در اینجا فهرست می‌شوند." : "جست‌وجو را تغییر دهید یا کالای تازه اضافه کنید."}/>}</div></section>
    {edit !== false && <Modal title={edit ? "ویرایش کالا" : "ثبت کالای جدید"} onClose={() => setEdit(false)}><form className="form-grid" onSubmit={save}><Field label="نام کالا" full><input required autoFocus value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="مثلاً روغن آفتابگردان"/></Field><Field label="کد کالا"><input required value={form.sku} onChange={(e) => setForm({ ...form, sku: e.target.value })} placeholder="G-1004"/></Field><Field label="بارکد"><input value={form.barcode} onChange={(e) => setForm({ ...form, barcode: e.target.value })} placeholder="اسکن یا وارد کنید"/></Field><Field label="قیمت فروش (افغانی)"><input required type="number" min="0" value={form.price} onChange={(e) => setForm({ ...form, price: numberValue(e) })}/></Field><Field label="قیمت خرید (افغانی)"><input type="number" min="0" value={form.cost} onChange={(e) => setForm({ ...form, cost: numberValue(e) })}/></Field><Field label="موجودی فعلی"><input type="number" min="0" disabled={Boolean(edit)} value={form.stock} onChange={(e) => setForm({ ...form, stock: numberValue(e) })}/></Field><Field label="حداقل موجودی"><input type="number" min="0" value={form.minStock} onChange={(e) => setForm({ ...form, minStock: numberValue(e) })}/></Field><Field label="واحد"><input value={form.unit} onChange={(e) => setForm({ ...form, unit: e.target.value })} placeholder="عدد، بسته، بوتل"/></Field><Field label="دسته‌بندی"><select value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })}><option value="">بدون دسته</option>{categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></Field>{error && <div className="form-error full">{error}</div>}<div className="form-actions full"><button type="button" className="secondary-button" onClick={() => setEdit(false)}>انصراف</button><button className="primary-button" disabled={busy}>{busy ? "در حال ذخیره…" : "ذخیره کالا"}</button></div></form></Modal>}
  </div>;
}

export function CategoriesPage({ notify }: { notify: Notify }) {
  const [categories, setCategories] = useState<Category[]>([]); const [name, setName] = useState(""); const [color, setColor] = useState("#7488a3"); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const load = () => get<Category[]>("/categories").then(setCategories).catch((e) => setError(e.message)); useEffect(() => { void load(); }, []);
  const save = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { await post("/categories", { name, color }); setName(""); notify("دسته‌بندی ثبت شد."); await load(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <div className="split-layout"><section className="surface"><SectionHead title="دسته‌بندی‌ها" subtitle="کالاها را برای دسترسی آسان گروه‌بندی کنید"/>{error && <ErrorBox message={error}/>}<div className="category-grid">{categories.map((c) => <article className="category-card" key={c.id}><span style={{ background: c.color }}/><div><b>{c.name}</b><small>{c._count?.products ?? 0} کالا</small></div></article>)}</div>{!categories.length && <Empty title="دسته‌ای ثبت نشده" text="برای شروع یک دسته‌بندی بسازید."/>}</section><section className="surface"><SectionHead title="دسته تازه" subtitle="نام و رنگ دسته را انتخاب کنید"/><form className="form-grid single" onSubmit={save}><Field label="نام دسته"><input required autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="مثلاً نوشیدنی"/></Field><Field label="رنگ دسته"><div className="color-picker"><input type="color" value={color} onChange={(e) => setColor(e.target.value)}/><span>{color}</span></div></Field><button className="primary-button" disabled={busy}><CirclePlus size={17}/> افزودن دسته</button></form></section></div>;
}

export function ContactsPage({ kind, notify }: { kind: "customers" | "suppliers"; notify: Notify }) {
  const [contacts, setContacts] = useState<Contact[]>([]); const [query, setQuery] = useState(""); const [show, setShow] = useState(false); const [editing, setEditing] = useState<Contact | null>(null); const [form, setForm] = useState({ name: "", phone: "", address: "", note: "" }); const [error, setError] = useState(""); const [account, setAccount] = useState<CustomerDetail | SupplierDetail | null>(null); const [payForm, setPayForm] = useState({ amount: 0, note: "" }); const [payBusy, setPayBusy] = useState(false); const title = kind === "customers" ? "مشتریان" : "تأمین‌کنندگان"; const endpoint = `/${kind}`;
  const load = () => get<Contact[]>(endpoint).then(setContacts).catch((e) => setError(e.message)); useEffect(() => { void load(); }, [endpoint]);
  const openAccount = (contact: Contact) => { setPayForm({ amount: 0, note: "" }); get<CustomerDetail | SupplierDetail>(`${endpoint}/${contact.id}`).then(setAccount).catch((e) => notify(e.message, "error")); };
  const submitPayment = async (event: FormEvent) => {
    event.preventDefault();
    if (!account) return;
    const contactId = "customer" in account ? account.customer.id : account.supplier.id;
    setPayBusy(true);
    try {
      await post(`${endpoint}/${contactId}/payments`, { amount: payForm.amount, note: payForm.note || undefined });
      notify(kind === "customers" ? "پرداخت نسیه ثبت شد." : "پرداخت به تأمین‌کننده ثبت شد.");
      const fresh = await get<CustomerDetail | SupplierDetail>(`${endpoint}/${contactId}`);
      setAccount(fresh); setPayForm({ amount: 0, note: "" });
    } catch (e) { notify((e as Error).message, "error"); } finally { setPayBusy(false); }
  };
  const filtered = contacts.filter((c) => `${c.name} ${c.phone || ""}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()));
  const open = (contact?: Contact) => { setEditing(contact || null); setForm(contact ? { name: contact.name, phone: contact.phone || "", address: contact.address || "", note: contact.note || "" } : { name: "", phone: "", address: "", note: "" }); setShow(true); };
  const save = async (event: FormEvent) => { event.preventDefault(); setError(""); try { if (editing) await patch(`${endpoint}/${editing.id}`, form); else await post(endpoint, form); setShow(false); notify(`${title} ذخیره شد.`); await load(); } catch (e) { setError((e as Error).message); } };
  return <div className="page-stack"><section className="surface"><SectionHead title={`فهرست ${title}`} subtitle={`${contacts.length} مورد ثبت شده`} action={<button className="primary-button" onClick={() => open()}><CirclePlus size={18}/> افزودن {kind === "customers" ? "مشتری" : "تأمین‌کننده"}</button>}/><div className="toolbar"><div className="search-box"><Search size={17}/><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="جست‌وجوی نام یا شماره تماس…"/></div><span className="toolbar-count">{filtered.length} مورد</span></div>{error && <ErrorBox message={error}/>}<div className="table-wrap"><table><thead><tr><th>نام</th><th>{kind === "customers" ? "بدهی نسیه" : "بدهی"}</th><th>شماره تماس</th><th>نشانی</th><th>یادداشت</th><th></th></tr></thead><tbody>{filtered.map((c) => <tr key={c.id}><td><div className="cell-main"><span className="avatar pale">{c.name.slice(0, 1)}</span><b>{c.name}</b></div></td><td><b className={(c.balance || 0) > 0 ? "danger-text" : "green-text"}>{(c.balance || 0) > 0 ? money(c.balance!) : "تسویه"}</b></td><td dir="ltr" className="text-right">{c.phone || "—"}</td><td>{c.address || "—"}</td><td className="muted">{c.note || "—"}</td><td><div className="row-actions"><button className="text-button" onClick={() => openAccount(c)}><Wallet size={14}/> حساب</button><button className="text-button" onClick={() => open(c)}>ویرایش</button></div></td></tr>)}</tbody></table>{!filtered.length && <Empty title="موردی پیدا نشد" text="اطلاعات را بررسی کنید یا مورد تازه‌ای ثبت کنید."/>}</div></section>
    {show && <Modal title={`${editing ? "ویرایش" : "افزودن"} ${kind === "customers" ? "مشتری" : "تأمین‌کننده"}`} onClose={() => setShow(false)}><form className="form-grid" onSubmit={save}><Field label="نام" full><input required autoFocus value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })}/></Field><Field label="شماره تماس"><input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} dir="ltr"/></Field><Field label="نشانی"><input value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })}/></Field><Field label="یادداشت" full><textarea rows={3} value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })}/></Field>{error && <div className="form-error full">{error}</div>}<div className="form-actions full"><button type="button" className="secondary-button" onClick={() => setShow(false)}>انصراف</button><button className="primary-button">ذخیره</button></div></form></Modal>}
    {account && <Modal title={"customer" in account ? `حساب نسیهٔ ${account.customer.name}` : `حساب ${account.supplier.name}`} onClose={() => setAccount(null)}>
      {"customer" in account ? <div className="metric-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}><Metric icon={Wallet} label="مانده بدهی" value={money(account.balance)} note="نسیهٔ پرداخت‌نشده" tone={account.balance > 0 ? "amber" : "green"}/><Metric icon={ShoppingCart} label="فروش نسیه" value={money(account.creditSales)} note="مجموع فاکتورهای نسیه" tone="violet"/><Metric icon={Check} label="پرداخت‌شده" value={money(account.creditReturns + account.paymentsTotal)} note="برگشتی + وصولی" tone="blue"/></div>
        : <div className="metric-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}><Metric icon={Wallet} label="مانده بدهی" value={money(account.balance)} note="خریدهای پرداخت‌نشده" tone={account.balance > 0 ? "amber" : "green"}/><Metric icon={Truck} label="جمع خریدها" value={money(account.purchasesTotal)} note="از این تأمین‌کننده" tone="violet"/><Metric icon={Check} label="پرداخت‌شده" value={money(account.paidAtPurchase + account.paymentsTotal)} note="هنگام خرید + بعد از آن" tone="blue"/></div>}
      <form className="form-grid single" onSubmit={submitPayment}><Field label={kind === "customers" ? "ثبت پرداخت نسیه (افغانی)" : "ثبت پرداخت به تأمین‌کننده (افغانی)"}><input required type="number" min="1" autoFocus value={payForm.amount} onChange={(e) => setPayForm({ ...payForm, amount: numberValue(e) })}/></Field><Field label="یادداشت"><input value={payForm.note} onChange={(e) => setPayForm({ ...payForm, note: e.target.value })} placeholder="اختیاری"/></Field>{kind === "customers" && payForm.amount > 0 && account.balance > 0 && payForm.amount > account.balance && <div className="hint-box">این مبلغ از مانده بدهی (<b>{money(account.balance)}</b>) بیشتر است؛ مازاد به‌عنوان اعتبار ثبت می‌شود.</div>}{kind === "suppliers" && <div className="hint-box"><ShieldCheck size={17}/> این پرداخت فقط در حساب تأمین‌کننده ثبت می‌شود و نقد صندوق را تغییر نمی‌دهد؛ اگر از صندوق پرداخت کردید، آن را در بخش «مدیریت صندوق» ثبت کنید.</div>}<div className="form-actions"><button type="button" className="secondary-button" onClick={() => setAccount(null)}>بستن</button><button className="primary-button" disabled={payBusy || payForm.amount <= 0}>{payBusy ? "در حال ثبت…" : "ثبت پرداخت"}</button></div></form>
      {account.payments.length ? <div className="table-wrap"><table><thead><tr><th>مبلغ</th><th>یادداشت</th><th>ثبت‌کننده</th><th>زمان</th></tr></thead><tbody>{account.payments.map((p) => <tr key={p.id}><td className="strong green-text">{money(p.amount)}</td><td className="muted">{p.note || "—"}</td><td>{p.user?.displayName || "—"}</td><td className="muted">{dateTime(p.createdAt)}</td></tr>)}</tbody></table></div> : <Empty title="پرداختی ثبت نشده" text={kind === "customers" ? "پرداخت‌های نسیهٔ این مشتری در اینجا دیده می‌شوند." : "پرداخت‌های این تأمین‌کننده در اینجا دیده می‌شوند."}/>}
      {kind === "suppliers" && (account as SupplierDetail).recentPurchases.length > 0 && <div className="table-wrap" style={{ marginTop: "0.75rem" }}><table><thead><tr><th>رسید خرید</th><th>مبلغ</th><th>پرداخت‌شده</th><th>زمان</th></tr></thead><tbody>{(account as SupplierDetail).recentPurchases.map((purchase) => <tr key={purchase.id}><td className="mono">{purchase.invoiceNo || "—"}</td><td className="strong">{money(purchase.total)}</td><td>{money(purchase.paidAmount)}{purchase.paidAmount < purchase.total && <small className="block stock-low">بدهی: {money(purchase.total - purchase.paidAmount)}</small>}</td><td className="muted">{dateTime(purchase.createdAt)}</td></tr>)}</tbody></table></div>}
    </Modal>}
  </div>;
}

export function PosPage({ notify }: { notify: Notify }) {
  const [products, setProducts] = useState<Product[]>([]); const [customers, setCustomers] = useState<Contact[]>([]); const [cash, setCash] = useState<CashSession | null>(null); const [query, setQuery] = useState(""); const [cart, setCart] = useState<Record<string, number>>({}); const [customerId, setCustomerId] = useState(""); const [payment, setPayment] = useState<"CASH" | "MOBILE" | "CREDIT">("CASH"); const [discount, setDiscount] = useState(0); const [paid, setPaid] = useState(0); const [error, setError] = useState(""); const [saving, setSaving] = useState(false); const [receipt, setReceipt] = useState<Sale | null>(null); const [shop, setShop] = useState<ShopSettings>({});
  const load = () => Promise.all([get<Product[]>("/products"), get<Contact[]>("/customers"), get<CashSession | null>("/cash/current"), get<ShopSettings>("/settings")]).then(([p, c, s, settings]) => { setProducts(p); setCustomers(c); setCash(s); setShop(settings); }).catch((e) => setError(e.message)); useEffect(() => { void load(); }, []);
  const cartItems = useMemo(() => Object.entries(cart).map(([id, quantity]) => { const product = products.find((p) => p.id === id)!; return { product, quantity }; }).filter((line) => line.product), [cart, products]);
  const subtotal = cartItems.reduce((sum, line) => sum + line.product.price * line.quantity, 0); const total = Math.max(0, subtotal - discount);
  useEffect(() => { if (payment !== "CASH") setPaid(total); else if (paid === 0 || paid < total) setPaid(total); }, [total, payment]);
  const filtered = products.filter((p) => `${p.name} ${p.sku} ${p.barcode || ""}`.toLowerCase().includes(query.toLowerCase())).slice(0, 40);
  const add = (product: Product) => { setError(""); setCart((previous) => { const current = previous[product.id] || 0; if (current >= product.stock) { setError(`موجودی ${product.name} بیشتر از ${product.stock} نیست.`); return previous; } return { ...previous, [product.id]: current + 1 }; }); setPaid(total); };
  const scan = (event: FormEvent) => { event.preventDefault(); const exact = products.find((p) => p.barcode === query.trim() || p.sku.toLowerCase() === query.trim().toLowerCase()); if (exact) { add(exact); setQuery(""); } else if (query.trim()) setError("کالایی با این بارکد یا کد پیدا نشد."); };
  const quantity = (id: string, change: number) => setCart((previous) => { const next = (previous[id] || 0) + change; if (next <= 0) { const copy = { ...previous }; delete copy[id]; return copy; } const product = products.find((p) => p.id === id); if (product && next > product.stock) { setError(`موجودی ${product.name} کافی نیست.`); return previous; } return { ...previous, [id]: next }; });
  const checkout = async () => { if (!cartItems.length) return; if (discount > subtotal) { setError("تخفیف نمی‌تواند بیشتر از جمع فاکتور باشد."); return; } setSaving(true); setError(""); try { const sale = await post<Sale>("/sales", { items: cartItems.map(({ product, quantity }) => ({ productId: product.id, quantity })), customerId: customerId || undefined, paymentMethod: payment, discount, amountPaid: payment === "CREDIT" ? 0 : paid }, { "Idempotency-Key": crypto.randomUUID() }); setReceipt(sale); setCart({}); setDiscount(0); setCustomerId(""); setPaid(0); await load(); notify("فروش با موفقیت ثبت شد."); } catch (e) { setError((e as Error).message); } finally { setSaving(false); } };
  return <div className="pos-layout">
    <section className="pos-products surface"><div className="pos-title"><div><h2>انتخاب کالا</h2><p>بارکد را اسکن یا نام کالا را جست‌وجو کنید.</p></div><span className="live-status"><i/> آماده</span></div><form className="search-box pos-search" onSubmit={scan}><Search size={19}/><input autoFocus value={query} onChange={(e) => setQuery(e.target.value)} placeholder="نام کالا یا بارکد را وارد کنید…"/><kbd>Enter</kbd></form>{error && <ErrorBox message={error}/>}<div className="pos-product-grid">{filtered.map((p) => <button key={p.id} className={`pos-product ${p.stock <= 0 ? "disabled" : ""}`} disabled={p.stock <= 0} onClick={() => add(p)}><div className="pos-product-art" style={{ background: p.category?.color || "#8494a5" }}>{p.name.slice(0, 1)}</div><span className="pos-product-name">{p.name}</span><span className="pos-product-bottom"><b>{money(p.price)}</b><small className={p.stock <= p.minStock ? "stock-low" : ""}>{p.stock} {p.unit}</small></span></button>)}{!filtered.length && <Empty title="کالایی پیدا نشد" text="نام یا بارکد دیگری را جست‌وجو کنید."/>}</div></section>
    <aside className="cart-panel surface"><div className="cart-heading"><div><h2>فاکتور فروش</h2><p>{cartItems.reduce((n, line) => n + line.quantity, 0)} قلم کالا</p></div><button className="text-button danger-text" onClick={() => setCart({})}>پاک‌کردن</button></div><div className="cart-lines">{cartItems.length ? cartItems.map(({ product, quantity: qty }) => <article className="cart-line" key={product.id}><div className="cart-line-title"><b>{product.name}</b><small>{money(product.price)} / {product.unit}</small></div><div className="quantity-control"><button onClick={() => quantity(product.id, -1)}>−</button><b>{qty}</b><button onClick={() => quantity(product.id, 1)}>+</button></div><strong>{money(product.price * qty)}</strong></article>) : <div className="cart-empty"><div><ShoppingBag size={24}/></div><b>فاکتور خالی است</b><span>برای افزودن کالا روی آن بزنید.</span></div>}</div>
      <div className="cart-options"><label className="compact-field"><span>مشتری</span><select value={customerId} onChange={(e) => setCustomerId(e.target.value)}><option value="">مشتری گذری</option>{customers.filter((c) => c.name !== "مشتری گذری").map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="compact-field"><span>روش پرداخت</span><select value={payment} onChange={(e) => setPayment(e.target.value as typeof payment)}><option value="CASH">نقدی</option><option value="MOBILE">پرداخت موبایلی</option><option value="CREDIT">قرض / نسیه</option></select></label><div className="discount-line"><span>تخفیف (افغانی)</span><input type="number" min="0" max={subtotal} value={discount} onChange={(e) => setDiscount(numberValue(e))}/></div>{payment !== "CREDIT" && <div className="discount-line"><span>{payment === "CASH" ? "مبلغ دریافتی" : "مبلغ پرداخت‌شده"}</span><input type="number" min={payment === "CASH" ? total : 0} value={paid} onChange={(e) => setPaid(numberValue(e))}/></div>}</div>
      <div className="cart-totals"><div><span>جمع کالاها</span><b>{money(subtotal)}</b></div>{discount > 0 && <div><span>تخفیف</span><b className="danger-text">− {money(discount)}</b></div>}<div className="grand-total"><span>مبلغ نهایی</span><strong>{money(total)}</strong></div>{payment === "CASH" && paid > total && <div><span>باقی‌پول مشتری</span><b>{money(paid - total)}</b></div>}</div>
      {!cash && <div className="error-box cash-warning"><AlertTriangle size={16}/> صندوق باز نیست؛ برای فروش نقدی ابتدا صندوق را باز کنید.</div>}<button className="checkout-button" disabled={!cartItems.length || saving || (payment === "CASH" && !cash) || (payment !== "CREDIT" && paid < total)} onClick={() => void checkout()}><Check size={19}/>{saving ? "در حال ثبت فروش…" : "ثبت فروش"}<span>{money(total)}</span></button><div className="cart-footnote"><ShieldCheck size={14}/> ثبت فروش و کاهش موجودی باهم ذخیره می‌شوند.</div>
    </aside>
    {receipt && <Modal title="فروش ثبت شد" onClose={() => setReceipt(null)}><div className="receipt-print" id="receipt-print"><div className="receipt-brand">روشن</div><p>{shop.shopName?.trim() || "فروشگاه من"}</p><div className="receipt-divider"/><div className="receipt-meta"><span>شماره فاکتور</span><b>{receipt.receiptNo}</b></div><div className="receipt-meta"><span>زمان</span><b>{dateTime(receipt.createdAt)}</b></div><div className="receipt-meta"><span>مشتری</span><b>{receipt.customer?.name || "مشتری گذری"}</b></div><div className="receipt-divider"/>{receipt.items.map((item) => <div className="receipt-item" key={item.id}><span>{item.name} × {item.quantity}</span><b>{money(item.lineTotal)}</b></div>)}<div className="receipt-divider"/><div className="receipt-meta"><span>جمع کل</span><strong>{money(receipt.total)}</strong></div>{receipt.discount > 0 && <div className="receipt-meta"><span>تخفیف</span><b>{money(receipt.discount)}</b></div>}<div className="receipt-meta"><span>پرداخت</span><b>{receipt.paymentMethod === "CASH" ? "نقدی" : receipt.paymentMethod === "MOBILE" ? "موبایلی" : "نسیه"}</b></div><p className="receipt-thanks">{shop.receiptFooter?.trim() || "از خرید شما سپاس‌گزاریم"}</p></div><div className="form-actions"><button className="secondary-button" onClick={() => setReceipt(null)}>بستن</button><button className="primary-button" onClick={() => window.print()}><Printer size={17}/> چاپ رسید</button></div></Modal>}
  </div>;
}

type InventoryMovement = { id: string; type: string; quantity: number; stockAfter: number; reference: string | null; note: string | null; createdAt: string; product: { name: string; sku: string; unit: string } };
export function InventoryPage({ notify }: { notify: Notify }) {
  const [movements, setMovements] = useState<InventoryMovement[]>([]); const [products, setProducts] = useState<Product[]>([]); const [query, setQuery] = useState(""); const [show, setShow] = useState(false); const [form, setForm] = useState({ productId: "", quantity: 1, direction: "IN", note: "" }); const [error, setError] = useState("");
  const load = () => Promise.all([get<InventoryMovement[]>("/inventory/movements"), get<Product[]>("/products")]).then(([m, p]) => { setMovements(m); setProducts(p); if (!form.productId && p[0]) setForm((old) => ({ ...old, productId: p[0].id })); }).catch((e) => setError(e.message)); useEffect(() => { void load(); }, []);
  const filtered = movements.filter((m) => `${m.product.name} ${m.product.sku} ${m.reference || ""}`.toLowerCase().includes(query.toLowerCase()));
  const save = async (event: FormEvent) => { event.preventDefault(); setError(""); try { await post("/inventory/adjust", { productId: form.productId, quantity: form.direction === "IN" ? Math.abs(form.quantity) : -Math.abs(form.quantity), note: form.note || undefined }); setShow(false); notify("موجودی انبار تعدیل شد."); await load(); } catch (e) { setError((e as Error).message); } };
  return <div className="page-stack"><div className="metric-grid inventory-metrics"><Metric icon={Boxes} label="تعداد کالاها" value={String(products.length)} note="کالاهای فعال" tone="blue"/><Metric icon={Package} label="جمع واحدهای موجود" value={new Intl.NumberFormat("fa-AF").format(products.reduce((n, p) => n + p.stock, 0))} note="تمام کالاها" tone="green"/><Metric icon={Banknote} label="ارزش انبار" value={money(products.reduce((n, p) => n + p.stock * p.cost, 0))} note="به قیمت خرید" tone="violet"/><Metric icon={AlertTriangle} label="زیر حداقل موجودی" value={String(products.filter((p) => p.stock <= p.minStock).length)} note="نیازمند سفارش یا بررسی" tone="amber"/></div><section className="surface"><SectionHead title="گردش موجودی" subtitle="فروش، ورود و تعدیل کالاها" action={<button className="primary-button" onClick={() => setShow(true)}><ArrowDownUp size={17}/> تعدیل موجودی</button>}/><div className="toolbar"><div className="search-box"><Search size={17}/><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="جست‌وجوی کالا یا شماره فاکتور…"/></div></div>{error && <ErrorBox message={error}/>}<div className="table-wrap"><table><thead><tr><th>کالا</th><th>نوع گردش</th><th>تعداد</th><th>موجودی پس از عملیات</th><th>مرجع / توضیح</th><th>زمان</th></tr></thead><tbody>{filtered.map((m) => <tr key={m.id}><td><b>{m.product.name}</b><small className="block muted">{m.product.sku}</small></td><td><span className={`status-pill ${m.quantity >= 0 ? "paid" : "warning"}`}>{movementLabel(m.type)}</span></td><td className={m.quantity < 0 ? "danger-text" : "green-text"}>{m.quantity > 0 ? "+" : ""}{m.quantity} {m.product.unit}</td><td>{m.stockAfter} {m.product.unit}</td><td className="muted">{m.reference || m.note || "—"}</td><td className="muted">{dateTime(m.createdAt)}</td></tr>)}</tbody></table>{!filtered.length && <Empty title="گردشی ثبت نشده" text="ورود و خروج کالاها پس از ثبت نمایش داده می‌شود."/>}</div></section>
    {show && <Modal title="تعدیل موجودی" onClose={() => setShow(false)}><form className="form-grid single" onSubmit={save}><Field label="کالا"><select required value={form.productId} onChange={(e) => setForm({ ...form, productId: e.target.value })}><option value="">انتخاب کالا</option>{products.map((p) => <option key={p.id} value={p.id}>{p.name} — {p.stock} {p.unit}</option>)}</select></Field><Field label="نوع عملیات"><select value={form.direction} onChange={(e) => setForm({ ...form, direction: e.target.value })}><option value="IN">افزایش موجودی</option><option value="OUT">کاهش موجودی</option></select></Field><Field label="تعداد"><input type="number" required min="1" value={Math.abs(form.quantity)} onChange={(e) => setForm({ ...form, quantity: numberValue(e) })}/></Field><Field label="یادداشت"><input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} placeholder="دلیل تعدیل"/></Field>{error && <div className="form-error">{error}</div>}<div className="form-actions"><button type="button" className="secondary-button" onClick={() => setShow(false)}>انصراف</button><button className="primary-button">ثبت تعدیل</button></div></form></Modal>}
  </div>;
}
function movementLabel(type: string) { return ({ SALE: "فروش", PURCHASE: "خرید", ADJUSTMENT_IN: "ورود دستی", ADJUSTMENT_OUT: "خروج دستی", SALE_RETURN: "برگشت فروش" } as Record<string, string>)[type] || type; }

type PurchaseLine = { productId: string; quantity: number; unitCost: number };
export function PurchasesPage({ notify }: { notify: Notify }) {
  const [purchases, setPurchases] = useState<Purchase[]>([]); const [products, setProducts] = useState<Product[]>([]); const [suppliers, setSuppliers] = useState<Contact[]>([]); const [query, setQuery] = useState(""); const [show, setShow] = useState(false); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const [viewing, setViewing] = useState<Purchase | null>(null);
  const [form, setForm] = useState({ supplierId: "", invoiceNo: "", note: "" }); const [lines, setLines] = useState<PurchaseLine[]>([]); const [paid, setPaid] = useState(0); const [paidTouched, setPaidTouched] = useState(false);
  const load = () => Promise.all([get<Purchase[]>("/purchases"), get<Product[]>("/products"), get<Contact[]>("/suppliers")]).then(([list, productList, supplierList]) => { setPurchases(list); setProducts(productList); setSuppliers(supplierList); }).catch((e) => setError(e.message));
  useEffect(() => { void load(); }, []);
  const filtered = purchases.filter((p) => `${p.invoiceNo || ""} ${p.supplier?.name || ""} ${p.user?.displayName || ""}`.includes(query));
  const total = lines.reduce((sum, line) => sum + line.quantity * line.unitCost, 0);
  const effectivePaid = Math.min(paidTouched ? paid : total, total);
  const addLine = () => { const first = products[0]; if (!first) return; setLines([...lines, { productId: first.id, quantity: 1, unitCost: first.cost }]); };
  const updateLine = (index: number, changes: Partial<PurchaseLine>) => setLines(lines.map((line, i) => (i === index ? { ...line, ...changes } : line)));
  const removeLine = (index: number) => setLines(lines.filter((_, i) => i !== index));
  const save = async (event: FormEvent) => {
    event.preventDefault(); setError(""); setBusy(true);
    const merged = new Map<string, { quantity: number; unitCost: number }>();
    for (const line of lines) merged.set(line.productId, { quantity: (merged.get(line.productId)?.quantity || 0) + line.quantity, unitCost: line.unitCost });
    const items = [...merged.entries()].map(([productId, data]) => ({ productId, ...data }));
    try {
      await post("/purchases", { items, supplierId: form.supplierId || undefined, invoiceNo: form.invoiceNo || undefined, note: form.note || undefined, paidAmount: effectivePaid });
      notify("خرید ثبت و موجودی انبار به‌روز شد.");
      setShow(false); setLines([]); setPaid(0); setPaidTouched(false); setForm({ supplierId: "", invoiceNo: "", note: "" }); await load();
    } catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  };
  return <div className="page-stack"><section className="surface"><SectionHead title="خرید و ورود کالا" subtitle="رسید خرید از تأمین‌کننده و افزایش خودکار موجودی" action={<button className="primary-button" disabled={!products.length} onClick={() => { setLines([]); setPaid(0); setPaidTouched(false); setShow(true); }}><Truck size={17}/> خرید جدید</button>}/><div className="toolbar"><div className="search-box"><Search size={17}/><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="جست‌وجوی شماره رسید یا تأمین‌کننده…"/></div><span className="toolbar-count">{filtered.length} رسید</span></div>{error && <ErrorBox message={error}/>}<div className="table-wrap"><table><thead><tr><th>رسید خرید</th><th>تأمین‌کننده</th><th>اقلام</th><th>مبلغ کل</th><th>پرداخت‌شده</th><th>ثبت‌کننده</th><th>زمان</th><th></th></tr></thead><tbody>{filtered.map((purchase) => <tr key={purchase.id}><td className="mono">{purchase.invoiceNo || `خرید ${dateOnly(purchase.createdAt)}`}</td><td>{purchase.supplier?.name || "—"}</td><td title={purchase.items.map((item) => `${item.name} × ${item.quantity}`).join("، ")}>{purchase.items.reduce((n, item) => n + item.quantity, 0)} قلم</td><td className="strong">{money(purchase.total)}</td><td>{money(purchase.paidAmount)}{purchase.paidAmount < purchase.total && <small className="block stock-low">بدهی: {money(purchase.total - purchase.paidAmount)}</small>}</td><td>{purchase.user?.displayName || "—"}</td><td className="muted">{dateTime(purchase.createdAt)}</td><td><button className="text-button" onClick={() => setViewing(purchase)}>مشاهده</button></td></tr>)}</tbody></table>{!filtered.length && <Empty title="رسید خریدی ثبت نشده" text="با ثبت خرید، کالاها به موجودی انبار اضافه و قیمت خرید به‌روز می‌شود."/>}</div></section>
    {show && <Modal title={lines.length ? "رسید خرید" : "ثبت خرید جدید"} wide onClose={() => setShow(false)}><form onSubmit={save}>
      <div className="form-grid"><Field label="تأمین‌کننده (اختیاری)"><select value={form.supplierId} onChange={(e) => setForm({ ...form, supplierId: e.target.value })}><option value="">بدون تأمین‌کننده</option>{suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="شماره رسید تأمین‌کننده (اختیاری)"><input value={form.invoiceNo} onChange={(e) => setForm({ ...form, invoiceNo: e.target.value })} placeholder="مثلاً INV-1201" dir="ltr"/></Field><Field label="یادداشت" full><input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} placeholder="اختیاری"/></Field></div>
      <div className="table-wrap" style={{ marginTop: "0.75rem" }}><table><thead><tr><th>کالا</th><th>تعداد</th><th>قیمت خرید واحد</th><th>جمع</th><th></th></tr></thead><tbody>{lines.map((line, index) => { return <tr key={index}><td><select value={line.productId} onChange={(e) => { const picked = products.find((p) => p.id === e.target.value); updateLine(index, { productId: e.target.value, unitCost: picked ? picked.cost : line.unitCost }); }} style={{ minWidth: "10rem" }}>{products.map((p) => <option key={p.id} value={p.id}>{p.name} — {p.sku}</option>)}</select></td><td><input type="number" min="1" required value={line.quantity} onChange={(e) => updateLine(index, { quantity: Math.max(1, Number(e.target.value) || 1) })} style={{ width: "5rem" }} dir="ltr"/></td><td><input type="number" min="0" required value={line.unitCost} onChange={(e) => updateLine(index, { unitCost: Math.max(0, Number(e.target.value) || 0) })} style={{ width: "7rem" }} dir="ltr"/></td><td className="strong">{money(line.quantity * line.unitCost)}</td><td><button type="button" className="icon-button" onClick={() => removeLine(index)} title="حذف قلم"><X size={16}/></button></td></tr>; })}{!lines.length && <tr><td colSpan={5} className="muted">قلمی اضافه نشده است.</td></tr>}</tbody></table></div>
      <div className="form-actions" style={{ justifyContent: "space-between" }}><button type="button" className="secondary-button" onClick={addLine}><CirclePlus size={16}/> افزودن قلم</button><span>جمع کل: <b>{money(total)}</b></span></div>
      <div className="form-grid"><Field label="پرداخت‌شده هنگام خرید (افغانی)"><div className="row-actions"><input required type="number" min="0" max={total} value={effectivePaid} onChange={(e) => { setPaidTouched(true); setPaid(Math.min(total, Math.max(0, Number(e.target.value) || 0))); }} style={{ width: "9rem" }} dir="ltr"/><button type="button" className="text-button" onClick={() => { setPaidTouched(true); setPaid(total); }}>کامل</button><button type="button" className="text-button danger-text" onClick={() => { setPaidTouched(true); setPaid(0); }}>نسیه</button></div></Field>{effectivePaid < total && <Field label="بدهی به تأمین‌کننده"><div className="hint-box" style={{ margin: 0 }}>مانده: <b>{money(total - effectivePaid)}</b> در حساب تأمین‌کننده ثبت می‌شود.</div></Field>}</div>
      <div className="hint-box"><ShieldCheck size={17}/> با ثبت خرید، موجودی انبار افزایش می‌یابد، گردش «خرید» ثبت می‌شود و قیمت خرید کالاها به‌روز می‌گردد.</div>
      {error && <div className="form-error">{error}</div>}
      <div className="form-actions"><button type="button" className="secondary-button" onClick={() => setShow(false)}>انصراف</button><button className="primary-button" disabled={busy || !lines.length}>{busy ? "در حال ثبت…" : "ثبت خرید"}</button></div>
    </form></Modal>}
    {viewing && <Modal title={viewing.invoiceNo ? `رسید خرید ${viewing.invoiceNo}` : "رسید خرید"} onClose={() => setViewing(null)}><div className="receipt-meta"><span>تأمین‌کننده</span><b>{viewing.supplier?.name || "—"}</b></div><div className="receipt-meta"><span>ثبت‌کننده</span><b>{viewing.user?.displayName || "—"}</b></div><div className="receipt-meta"><span>زمان</span><b>{dateTime(viewing.createdAt)}</b></div>{viewing.note && <div className="receipt-meta"><span>یادداشت</span><b>{viewing.note}</b></div>}<div className="table-wrap" style={{ marginTop: "0.75rem" }}><table><thead><tr><th>کالا</th><th>تعداد</th><th>قیمت خرید واحد</th><th>جمع</th></tr></thead><tbody>{viewing.items.map((item) => <tr key={item.id}><td><b>{item.name}</b><small className="block muted">{item.sku}</small></td><td>{item.quantity}</td><td>{money(item.unitCost)}</td><td className="strong">{money(item.lineTotal)}</td></tr>)}</tbody></table></div><div className="form-actions"><span>جمع کل: <b>{money(viewing.total)}</b>{viewing.paidAmount < viewing.total && <small className="block stock-low">پرداخت‌شده: {money(viewing.paidAmount)} · بدهی: {money(viewing.total - viewing.paidAmount)}</small>}</span><button className="secondary-button" onClick={() => setViewing(null)}>بستن</button></div></Modal>}
  </div>;
}

export function SalesPage({ notify }: { notify: Notify }) {
  const [sales, setSales] = useState<Sale[]>([]); const [query, setQuery] = useState(""); const [selected, setSelected] = useState<Sale | null>(null); const [error, setError] = useState(""); const [range, setRange] = useState({ from: "", to: "" }); const [shop, setShop] = useState<ShopSettings>({});
  const [returning, setReturning] = useState<Sale | null>(null); const [returnDetail, setReturnDetail] = useState<Sale | null>(null); const [returnLines, setReturnLines] = useState<Record<string, number>>({}); const [returnNote, setReturnNote] = useState(""); const [returnBusy, setReturnBusy] = useState(false); const [returnReceipt, setReturnReceipt] = useState<{ sale: Sale; record: SaleReturn } | null>(null);
  const load = (from = range.from, to = range.to) => { const params = new URLSearchParams(); if (from) params.set("from", from); if (to) params.set("to", to); const qs = params.toString(); return get<Sale[]>(qs ? `/sales?${qs}` : "/sales"); };
  useEffect(() => { load().then(setSales).catch((e) => setError(e.message)); get<ShopSettings>("/settings").then(setShop).catch(() => undefined); }, []);
  const applyRange = (from: string, to: string) => { setRange({ from, to }); load(from, to).then(setSales).catch((e) => setError(e.message)); };
  const filtered = sales.filter((sale) => `${sale.receiptNo} ${sale.customer?.name || ""} ${sale.user?.displayName || ""}`.toLowerCase().includes(query.toLowerCase()));
  const totalSum = filtered.reduce((sum, sale) => sum + sale.total, 0);
  const returnedQty = (sale: Sale | null, productId: string) => (sale?.returns || []).flatMap((record) => record.items || []).filter((item) => item.productId === productId).reduce((count, item) => count + item.quantity, 0);
  const openDetail = (sale: Sale) => { setSelected(sale); get<Sale>(`/sales/${sale.id}`).then(setSelected).catch(() => undefined); };
  const openReturn = (sale: Sale) => { setReturning(sale); setReturnDetail(null); setReturnLines({}); setReturnNote(""); get<Sale>(`/sales/${sale.id}`).then(setReturnDetail).catch((e) => notify(e.message, "error")); };
  const refundEstimate = returnDetail ? Object.entries(returnLines).reduce((sum, [productId, quantity]) => { const item = returnDetail.items.find((line) => line.productId === productId); return sum + (item ? item.unitPrice * quantity : 0); }, 0) : 0;
  const submitReturn = async (event: FormEvent) => {
    event.preventDefault();
    if (!returning) return;
    const items = Object.entries(returnLines).filter(([, quantity]) => quantity > 0).map(([productId, quantity]) => ({ productId, quantity }));
    if (!items.length) { notify("حداقل یک قلم را برای برگشت انتخاب کنید.", "error"); return; }
    setReturnBusy(true);
    try {
      const record = await post<SaleReturn>(`/sales/${returning.id}/return`, { items, note: returnNote || undefined });
      notify(`برگشتی ${record.returnNo} ثبت شد؛ مبلغ برگشتی: ${money(record.total)}.`);
      setReturning(null); setReturnDetail(null);
      setSelected(null); // only one printable receipt on screen at a time
      setReturnReceipt({ sale: { ...returning, returns: [...(returning.returns || []), record] }, record });
      load().then(setSales).catch(() => undefined);
    } catch (e) { notify((e as Error).message, "error"); } finally { setReturnBusy(false); }
  };
  const exportCsv = () => {
    const rows: string[][] = [["شماره فاکتور", "زمان", "مشتری", "صندوقدار", "پرداخت", "تعداد اقلام", "مبلغ", "تخفیف", "برگشتی"]];
    for (const sale of filtered) rows.push([
      sale.receiptNo, dateTime(sale.createdAt), sale.customer?.name || "مشتری گذری", sale.user?.displayName || "", payLabel(sale.paymentMethod),
      String(sale.items.reduce((count, item) => count + item.quantity, 0)), String(sale.total), String(sale.discount),
      String((sale.returns || []).reduce((sum, record) => sum + record.total, 0)),
    ]);
    const csv = `\uFEFF${rows.map((row) => row.map((cell) => `"${cell.split("\"").join("\"\"")}"`).join(",")).join("\r\n")}`;
    const link = document.createElement("a");
    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    link.download = `sales-${range.from || "all"}-${range.to || new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
    URL.revokeObjectURL(link.href);
  };
  return <div className="page-stack"><section className="surface"><SectionHead title="فروش‌های ثبت‌شده" subtitle="فاکتورها با فیلتر تاریخ و امکان برگشت کالا"/><div className="toolbar"><div className="search-box"><Search size={17}/><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="جست‌وجوی شماره فاکتور یا مشتری…"/></div><div className="date-filter" dir="ltr"><input type="date" value={range.from} onChange={(e) => applyRange(e.target.value, range.to)} title="از تاریخ"/><input type="date" value={range.to} onChange={(e) => applyRange(range.from, e.target.value)} title="تا تاریخ"/></div><button className="text-button" onClick={() => applyRange(new Date().toISOString().slice(0, 10), new Date().toISOString().slice(0, 10))}>امروز</button><button className="text-button" onClick={() => applyRange(new Date(Date.now() - 6 * 86400000).toISOString().slice(0, 10), new Date().toISOString().slice(0, 10))}>۷ روز اخیر</button>{(range.from || range.to) && <button className="text-button danger-text" onClick={() => applyRange("", "")}>حذف فیلتر</button>}<button className="text-button" onClick={exportCsv} disabled={!filtered.length} title="ذخیرهٔ فاکتورهای نمایش‌داده‌شده در فایل CSV">خروجی CSV</button><span className="toolbar-count">{filtered.length} فاکتور · جمع {money(totalSum)}</span></div>{error && <ErrorBox message={error}/>}<div className="table-wrap"><table><thead><tr><th>شماره فاکتور</th><th>مشتری</th><th>صندوقدار</th><th>اقلام</th><th>پرداخت</th><th>مبلغ</th><th>زمان</th><th></th></tr></thead><tbody>{filtered.map((sale) => <tr key={sale.id}><td className="mono">{sale.receiptNo}{(sale.returns?.length || 0) > 0 && <small className="block stock-low">برگشتی دارد</small>}</td><td>{sale.customer?.name || "مشتری گذری"}</td><td>{sale.user?.displayName || "—"}</td><td>{sale.items.reduce((n, i) => n + i.quantity, 0)} قلم</td><td><span className="category-label">{payLabel(sale.paymentMethod)}</span></td><td className="strong">{money(sale.total)}</td><td className="muted">{dateTime(sale.createdAt)}</td><td><div className="row-actions"><button className="text-button" onClick={() => openDetail(sale)}>جزئیات</button><button className="text-button" onClick={() => void openReturn(sale)}><Undo2 size={14}/> برگشت</button></div></td></tr>)}</tbody></table>{!filtered.length && <Empty title="فاکتوری برای نمایش نیست" text="فروش‌های ثبت‌شده در اینجا دیده می‌شوند."/>}</div></section>
    {selected && <Modal title="جزئیات فاکتور" onClose={() => setSelected(null)}><div className="receipt-print" id="receipt-print"><div className="receipt-brand">روشن</div><p>{shop.shopName?.trim() || "فروشگاه من"}</p><div className="receipt-divider"/><div className="receipt-meta"><span>شماره فاکتور</span><b>{selected.receiptNo}</b></div><div className="receipt-meta"><span>زمان</span><b>{dateTime(selected.createdAt)}</b></div><div className="receipt-meta"><span>مشتری</span><b>{selected.customer?.name || "مشتری گذری"}</b></div><div className="receipt-divider"/>{selected.items.map((item) => <div className="receipt-item" key={item.id}><span>{item.name} × {item.quantity}</span><b>{money(item.lineTotal)}</b></div>)}<div className="receipt-divider"/><div className="receipt-meta"><span>جمع کل</span><strong>{money(selected.total)}</strong></div>{selected.discount > 0 && <div className="receipt-meta"><span>تخفیف</span><b>{money(selected.discount)}</b></div>}<div className="receipt-meta"><span>روش پرداخت</span><b>{payLabel(selected.paymentMethod)}</b></div></div>{(selected.returns?.length || 0) > 0 && <div className="hint-box">برگشتی‌های این فاکتور: {selected.returns!.reduce((n, r) => n + r.total, 0) > 0 ? money(selected.returns!.reduce((n, r) => n + r.total, 0)) : ""} ({selected.returns!.map((r) => r.returnNo).join("، ")})</div>}<div className="form-actions"><button className="secondary-button" onClick={() => setSelected(null)}>بستن</button><button className="secondary-button" onClick={() => { setSelected(null); void openReturn(selected); }}><Undo2 size={17}/> برگشت کالا</button><button className="primary-button" onClick={() => window.print()}><Printer size={17}/> چاپ فاکتور</button></div></Modal>}
    {returning && <Modal title={`برگشت کالا — فاکتور ${returning.receiptNo}`} onClose={() => setReturning(null)}><form onSubmit={submitReturn}>
      <div className="hint-box">مقدار برگشتی هر قلم را وارد کنید. اگر همهٔ اقلام فاکتور برگشت داده شوند، مبلغ برگشتی برابر مبلغ نهایی فاکتور ({money(returning.total)}) است؛ در غیر آن صورت به قیمت هر قلم محاسبه می‌شود.</div>
      {!returnDetail && <Loading/>}
      {returnDetail && <div className="table-wrap"><table><thead><tr><th>کالا</th><th>قیمت واحد</th><th>خرید‌شده</th><th>قابل برگشت</th><th>مقدار برگشت</th></tr></thead><tbody>{returnDetail.items.map((item) => { const remaining = item.quantity - returnedQty(returnDetail, item.productId); return <tr key={item.id}><td><b>{item.name}</b><small className="block muted">{item.sku}</small></td><td>{money(item.unitPrice)}</td><td>{item.quantity}</td><td className={remaining <= 0 ? "muted" : "strong"}>{remaining}</td><td><input type="number" min="0" max={remaining} disabled={remaining <= 0} value={returnLines[item.productId] || 0} onChange={(e) => { const next = Math.min(remaining, Math.max(0, Number(e.target.value) || 0)); setReturnLines({ ...returnLines, [item.productId]: next }); }} style={{ width: "5rem" }} dir="ltr"/></td></tr>; })}</tbody></table></div>}
      {returnDetail && <div className="form-grid single" style={{ marginTop: "0.75rem" }}><Field label="یادداشت برگشت (اختیاری)"><input value={returnNote} onChange={(e) => setReturnNote(e.target.value)} placeholder="مثلاً کالا معیوب بود"/></Field></div>}
      {refundEstimate > 0 && <div className="hint-box">برآورد مبلغ برگشتی: <b>{money(refundEstimate)}</b>{returning.paymentMethod === "CASH" ? " (از صندوق باز کسر می‌شود)" : ""}</div>}
      <div className="form-actions"><button type="button" className="secondary-button" onClick={() => setReturning(null)}>انصراف</button><button className="danger-button" disabled={returnBusy || !returnDetail || Object.values(returnLines).every((quantity) => !quantity)}>{returnBusy ? "در حال ثبت…" : "ثبت برگشت"}</button></div>
    </form></Modal>}
    {returnReceipt && <Modal title="برگشت ثبت شد" onClose={() => setReturnReceipt(null)}><div className="receipt-print" id="receipt-print"><div className="receipt-brand">روشن</div><p>{shop.shopName?.trim() || "فروشگاه من"}</p><div className="receipt-divider"/><div className="receipt-meta"><span>شماره برگشتی</span><b>{returnReceipt.record.returnNo}</b></div><div className="receipt-meta"><span>فاکتور اصلی</span><b>{returnReceipt.sale.receiptNo}</b></div><div className="receipt-meta"><span>زمان</span><b>{dateTime(returnReceipt.record.createdAt)}</b></div><div className="receipt-divider"/>{(returnReceipt.record.items || []).map((item) => <div className="receipt-item" key={item.id}><span>{item.name} × {item.quantity}</span><b>{money(item.lineTotal)}</b></div>)}<div className="receipt-divider"/><div className="receipt-meta"><span>مبلغ برگشتی</span><strong>{money(returnReceipt.record.total)}</strong></div>{returnReceipt.record.note && <div className="receipt-meta"><span>یادداشت</span><b>{returnReceipt.record.note}</b></div>}<p className="receipt-thanks">{shop.receiptFooter?.trim() || "از خرید شما سپاس‌گزاریم"}</p></div><div className="form-actions"><button className="secondary-button" onClick={() => setReturnReceipt(null)}>بستن</button><button className="primary-button" onClick={() => window.print()}><Printer size={17}/> چاپ رسید برگشتی</button></div></Modal>}
  </div>;
}
function payLabel(method: Sale["paymentMethod"]) { return ({ CASH: "نقدی", MOBILE: "موبایلی", CREDIT: "نسیه" })[method]; }
function payLabelRaw(method: string) { return ({ CASH: "نقدی", MOBILE: "موبایلی", CREDIT: "نسیه" } as Record<string, string>)[method] || method; }

export function ReportsPage() {
  const today = new Date().toISOString().slice(0, 10);
  const monthAgo = new Date(Date.now() - 29 * 86400000).toISOString().slice(0, 10);
  const [range, setRange] = useState({ from: monthAgo, to: today });
  const [report, setReport] = useState<ProfitReport | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const apply = (from: string, to: string) => {
    setRange({ from, to }); setError(""); setBusy(true);
    const params = new URLSearchParams();
    if (from) params.set("from", from);
    if (to) params.set("to", to);
    get<ProfitReport>(`/reports/profit?${params.toString()}`).then(setReport).catch((e) => setError(e.message)).finally(() => setBusy(false));
  };
  useEffect(() => { apply(monthAgo, today); }, []);
  const dayLabel = (day: string) => new Intl.DateTimeFormat("fa-AF", { dateStyle: "medium" }).format(new Date(`${day}T00:00:00`));
  return <div className="page-stack">
    <section className="surface"><SectionHead title="گزارش سود و فروش" subtitle="سود ناخالص، پرفروش‌ترین کالاها و تفکیک روش پرداخت"/><div className="toolbar"><div className="date-filter" dir="ltr"><input type="date" value={range.from} onChange={(e) => apply(e.target.value, range.to)} title="از تاریخ"/><input type="date" value={range.to} onChange={(e) => apply(range.from, e.target.value)} title="تا تاریخ"/></div><button className="text-button" onClick={() => apply(today, today)}>امروز</button><button className="text-button" onClick={() => apply(new Date(Date.now() - 6 * 86400000).toISOString().slice(0, 10), today)}>۷ روز</button><button className="text-button" onClick={() => apply(monthAgo, today)}>۳۰ روز</button>{busy && <span className="toolbar-count">در حال محاسبه…</span>}</div>{error && <ErrorBox message={error}/>}
      {!report && !error && <Loading/>}
      {report && <div className="metric-grid">
        <Metric icon={Banknote} label="درآمد ناخالص" value={money(report.revenue)} note={`${report.invoiceCount} فاکتور`} tone="blue"/>
        <Metric icon={Undo2} label="بازپرداخت‌ها" value={money(report.refunds)} note="برگشتی‌های دوره" tone="amber"/>
        <Metric icon={ShoppingCart} label="درآمد خالص" value={money(report.netRevenue)} note="پس از کسر برگشتی" tone="violet"/>
        <Metric icon={Package} label="بهای کالای فروخته‌شده" value={money(report.cost)} note="به قیمت خرید" tone="blue"/>
        <Metric icon={Banknote} label="سود ناخالص" value={money(report.profit)} note="درآمد خالص − بهای کالا" tone="green"/>
        <Metric icon={Check} label="حاشیهٔ سود" value={`${new Intl.NumberFormat("fa-AF", { maximumFractionDigits: 0 }).format(report.margin * 100)}٪`} note="سود به ازای هر فروش" tone={report.profit >= 0 ? "green" : "amber"}/>
        <Metric icon={Truck} label="خرید دوره" value={money(report.purchasesTotal)} note="رسیدهای خرید ثبت‌شده" tone="violet"/>
        <Metric icon={Wallet} label="تفکیک پرداخت" value={money(report.paymentMix.reduce((sum, mix) => sum + mix.total, 0))} note={report.paymentMix.map((mix) => `${payLabelRaw(mix.method)} ${mix.count}`).join(" · ") || "—"} tone="amber"/>
      </div>}
      {report && report.unknownCostRevenue > 0 && <div className="hint-box"><AlertTriangle size={17}/> برای فروش‌هایی که پیش از نسخهٔ ۰.۳ ثبت شده‌اند بهای خرید در فاکتور ذخیره نشده است؛ سود این فروش‌ها ({money(report.unknownCostRevenue)}) بیش‌برآورد می‌شود. گزارش‌های تازه دقیق هستند.</div>}
    </section>
    {report && <div className="dashboard-grid">
      <section className="surface"><SectionHead title="فروش و سود روزانه" subtitle="روندهای بازهٔ انتخابی"/><div className="table-wrap"><table><thead><tr><th>روز</th><th>فروش خالص</th><th>سود</th></tr></thead><tbody>{[...report.byDay].reverse().map((row) => <tr key={row.day}><td>{dayLabel(row.day)}</td><td className="strong">{money(row.revenue)}</td><td className={row.profit >= 0 ? "green-text" : "danger-text"}>{money(row.profit)}</td></tr>)}</tbody></table>{!report.byDay.length && <Empty title="فروشی در این بازه نیست" text="بازهٔ دیگری را انتخاب کنید."/>}</div></section>
      <section className="surface"><SectionHead title="پرفروش‌ترین کالاها" subtitle="به ترتیب مبلغ فروش"/><div className="table-wrap"><table><thead><tr><th>کالا</th><th>تعداد</th><th>فروش</th><th>سود</th></tr></thead><tbody>{report.topProducts.map((product) => <tr key={product.productId}><td><b>{product.name}</b></td><td>{product.quantity}</td><td className="strong">{money(product.revenue)}</td><td className="green-text">{money(product.profit)}</td></tr>)}</tbody></table>{!report.topProducts.length && <Empty title="کالایی فروخته نشده" text="پس از ثبت فروش، پرفروش‌ها در اینجا دیده می‌شوند."/>}</div></section>
    </div>}
  </div>;
}

export function CashPage({ notify }: { notify: Notify }) {
  const [current, setCurrent] = useState<CashSession | null>(null); const [sessions, setSessions] = useState<CashSession[]>([]); const [show, setShow] = useState<"open" | "movement" | "close" | null>(null); const [form, setForm] = useState({ amount: 0, type: "IN", description: "", note: "" }); const [error, setError] = useState(""); const [saving, setSaving] = useState(false);
  const load = () => Promise.all([get<CashSession | null>("/cash/current"), get<CashSession[]>("/cash/sessions")]).then(([c, s]) => { setCurrent(c); setSessions(s); }).catch((e) => setError(e.message)); useEffect(() => { void load(); }, []);
  const save = async (event: FormEvent) => { event.preventDefault(); setError(""); setSaving(true); try { if (show === "open") await post("/cash/open", { openingCash: form.amount, note: form.note }); if (show === "movement") await post("/cash/movement", { amount: form.amount, type: form.type, description: form.description }); if (show === "close") { const result = await post<{ difference: number }>("/cash/close", { countedCash: form.amount, note: form.note }); notify(`صندوق بسته شد. اختلاف: ${money(result.difference)}.`, result.difference === 0 ? "success" : "error"); } else notify(show === "open" ? "صندوق باز شد." : "گردش صندوق ثبت شد."); setShow(null); setForm({ amount: 0, type: "IN", description: "", note: "" }); await load(); } catch (e) { setError((e as Error).message); } finally { setSaving(false); } };
  return <div className="page-stack"><section className={`cash-hero ${current ? "is-open" : "is-closed"}`}><div className="cash-hero-icon"><Banknote size={24}/></div><div className="grow"><span className="eyebrow">وضعیت نوبت کاری</span><h2>{current ? "صندوق باز است" : "صندوق بسته است"}</h2><p>{current ? `شروع: ${dateTime(current.openedAt)} · ${current.user?.displayName || "کاربر"}` : "برای ثبت فروش نقدی ابتدا صندوق را باز کنید."}</p></div><span className={`status-pill ${current ? "paid" : "warning"}`}>{current ? "فعال" : "بسته"}</span></section>
    {error && <ErrorBox message={error}/>}<div className="metric-grid cash-metrics"><Metric icon={Banknote} label="نقد آغازین" value={money(current?.openingCash ?? 0)} note="در ابتدای نوبت کاری" tone="blue"/><Metric icon={ShoppingCart} label="فروش نقدی" value={money(current?.cashSalesAmount ?? 0)} note="فاکتورهای پرداخت‌شده نقدی" tone="green"/><Metric icon={ArrowUpRight} label="مبلغ مورد انتظار" value={money(current?.expectedCash ?? 0)} note="نقد صندوق در پایان نوبت" tone="violet"/><Metric icon={FileText} label="نوبت‌های کاری" value={String(sessions.length)} note="سوابق صندوق" tone="amber"/></div>
    <section className="surface"><SectionHead title="عملیات صندوق" subtitle="ورودی‌ها و خروجی‌های نقدی را ثبت کنید" action={current ? <><button className="secondary-button" onClick={() => setShow("movement")}><ArrowDownUp size={16}/> ورود / خروج</button><button className="danger-button" onClick={() => { setForm({ amount: current.expectedCash, type: "IN", description: "", note: "" }); setShow("close"); }}>بستن صندوق</button></> : <button className="primary-button" onClick={() => { setForm({ amount: 0, type: "IN", description: "", note: "" }); setShow("open"); }}><CirclePlus size={17}/> باز کردن صندوق</button>}/>{current?.movements?.length ? <div className="movement-list">{current.movements.map((movement) => <div className="movement-row" key={movement.id}><div className={`movement-icon ${movement.type.toLowerCase()}`}>{movement.type === "IN" ? <ArrowDownLeft size={17}/> : <ArrowUpRight size={17}/>}</div><div className="grow"><b>{movement.description}</b><small>{movement.type === "IN" ? "ورودی نقدی" : "خروجی نقدی"}</small></div><strong className={movement.type === "IN" ? "green-text" : "danger-text"}>{movement.type === "IN" ? "+" : "−"}{money(movement.amount)}</strong></div>)}</div> : <Empty title="گردش دستی ثبت نشده" text="هزینه‌ها و ورودی‌های متفرقه صندوق را می‌توانید ثبت کنید."/>}</section>
    <section className="surface"><SectionHead title="سوابق صندوق" subtitle="آخرین نوبت‌های کاری"/><div className="table-wrap"><table><thead><tr><th>شروع</th><th>صندوقدار</th><th>نقد آغازین</th><th>مورد انتظار</th><th>نقد شمارش‌شده</th><th>وضعیت</th></tr></thead><tbody>{sessions.map((session) => <tr key={session.id}><td>{dateTime(session.openedAt)}</td><td>{session.user?.displayName || "—"}</td><td>{money(session.openingCash)}</td><td>{money(session.expectedCash || 0)}</td><td>{session.countedCash === null ? "—" : money(session.countedCash)}</td><td><span className={`status-pill ${session.status === "OPEN" ? "paid" : "neutral"}`}>{session.status === "OPEN" ? "باز" : "بسته"}</span></td></tr>)}</tbody></table>{!sessions.length && <Empty title="سابقه‌ای نیست" text="با بازکردن صندوق، نوبت کاری ثبت می‌شود."/>}</div></section>
    {show && <Modal title={show === "open" ? "باز کردن صندوق" : show === "close" ? "بستن صندوق" : "ثبت گردش نقدی"} onClose={() => setShow(null)}><form className="form-grid single" onSubmit={save}><Field label={show === "open" ? "نقد آغازین (افغانی)" : show === "close" ? "مبلغ شمارش‌شده (افغانی)" : "مبلغ (افغانی)"}><input required type="number" min="0" autoFocus value={form.amount} onChange={(e) => setForm({ ...form, amount: numberValue(e) })}/></Field>{show === "movement" && <><Field label="نوع گردش"><select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}><option value="IN">ورودی</option><option value="OUT">خروجی</option></select></Field><Field label="شرح"><input required value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="مثلاً هزینه حمل‌ونقل"/></Field></>}{show !== "movement" && <Field label="یادداشت"><input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })}/></Field>}{show === "close" && current && <div className="hint-box">مبلغ مورد انتظار: <b>{money(current.expectedCash)}</b> · اختلاف پس از بستن نشان داده می‌شود.</div>}{error && <div className="form-error">{error}</div>}<div className="form-actions"><button type="button" className="secondary-button" onClick={() => setShow(null)}>انصراف</button><button className={show === "close" ? "danger-button" : "primary-button"} disabled={saving}>{saving ? "در حال ثبت…" : show === "close" ? "بستن و ثبت شمارش" : "ذخیره"}</button></div></form></Modal>}
  </div>;
}

type ManagedUser = User & { isActive: boolean; createdAt: string };
export function UsersPage({ notify }: { notify: Notify }) {
  const [users, setUsers] = useState<ManagedUser[]>([]); const [show, setShow] = useState(false); const [error, setError] = useState(""); const [form, setForm] = useState({ username: "", displayName: "", password: "", role: "CASHIER" }); const [resetting, setResetting] = useState<ManagedUser | null>(null); const [newPassword, setNewPassword] = useState("");
  const load = () => get<ManagedUser[]>("/users").then(setUsers).catch((e) => setError(e.message)); useEffect(() => { void load(); }, []);
  const save = async (event: FormEvent) => { event.preventDefault(); setError(""); try { await post("/users", form); setShow(false); setForm({ username: "", displayName: "", password: "", role: "CASHIER" }); notify("کاربر ساخته شد."); await load(); } catch (e) { setError((e as Error).message); } };
  const deactivate = async (user: ManagedUser) => { if (!window.confirm(`دسترسی «${user.displayName}» بسته شود؟`)) return; try { await patch(`/users/${user.id}/deactivate`, {}); notify("دسترسی کاربر بسته شد."); await load(); } catch (e) { notify((e as Error).message, "error"); } };
  const activate = async (user: ManagedUser) => { try { await patch(`/users/${user.id}/activate`, {}); notify("دسترسی کاربر باز شد."); await load(); } catch (e) { notify((e as Error).message, "error"); } };
  const submitReset = async (event: FormEvent) => { event.preventDefault(); if (!resetting) return; try { await patch(`/users/${resetting.id}/reset-password`, { newPassword }); notify(`گذرواژهٔ «${resetting.displayName}» بازنشانی شد.`); setResetting(null); setNewPassword(""); } catch (e) { notify((e as Error).message, "error"); } };
  return <div className="page-stack"><section className="surface"><SectionHead title="کاربران فروشگاه" subtitle="برای هر فرد نام کاربری جداگانه بسازید" action={<button className="primary-button" onClick={() => setShow(true)}><CirclePlus size={17}/> کاربر جدید</button>}/>{error && <ErrorBox message={error}/>}<div className="table-wrap"><table><thead><tr><th>کاربر</th><th>نام ورود</th><th>نقش</th><th>وضعیت</th><th>ساخته‌شده</th><th></th></tr></thead><tbody>{users.map((user) => <tr key={user.id}><td><div className="cell-main"><span className="avatar pale">{user.displayName.slice(0, 1)}</span><b>{user.displayName}</b></div></td><td className="mono">{user.username}</td><td><span className="category-label">{user.role === "ADMIN" ? "مدیر" : "صندوقدار"}</span></td><td><span className={`status-pill ${user.isActive ? "paid" : "neutral"}`}>{user.isActive ? "فعال" : "بسته"}</span></td><td>{dateOnly(user.createdAt)}</td><td><div className="row-actions"><button className="text-button" onClick={() => { setResetting(user); setNewPassword(""); }}><KeyRound size={14}/> بازنشانی گذرواژه</button>{user.isActive ? <button className="text-button danger-text" onClick={() => void deactivate(user)}>بستن دسترسی</button> : <button className="text-button" onClick={() => void activate(user)}><Undo2 size={14}/> بازکردن دسترسی</button>}</div></td></tr>)}</tbody></table>{!users.length && <Empty title="کاربری ثبت نشده" text="یک حساب کاربری برای مدیر یا صندوقدار بسازید."/>}</div></section>
    <div className="hint-box"><ShieldCheck size={17}/> گذرواژه‌ها به‌صورت رمزگذاری‌شده نگهداری می‌شوند و ورود به سامانه فقط از همین دستگاه انجام می‌شود.</div>
    {show && <Modal title="ساخت کاربر" onClose={() => setShow(false)}><form className="form-grid single" onSubmit={save}><Field label="نام نمایشی"><input required autoFocus value={form.displayName} onChange={(e) => setForm({ ...form, displayName: e.target.value })}/></Field><Field label="نام کاربری"><input required minLength={3} value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} dir="ltr"/></Field><Field label="گذرواژه (حداقل ۸ نویسه)"><input required minLength={8} type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} dir="ltr"/></Field><Field label="نقش"><select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}><option value="CASHIER">صندوقدار</option><option value="ADMIN">مدیر</option></select></Field>{error && <div className="form-error">{error}</div>}<div className="form-actions"><button type="button" className="secondary-button" onClick={() => setShow(false)}>انصراف</button><button className="primary-button">ذخیره کاربر</button></div></form></Modal>}
    {resetting && <Modal title={`بازنشانی گذرواژهٔ ${resetting.displayName}`} onClose={() => setResetting(null)}><form className="form-grid single" onSubmit={submitReset}><Field label="گذرواژه تازه (حداقل ۸ نویسه)"><input required minLength={8} type="password" autoFocus value={newPassword} onChange={(e) => setNewPassword(e.target.value)} dir="ltr"/></Field><div className="hint-box"><ShieldCheck size={17}/> پس از بازنشانی، کاربر با گذرواژهٔ تازه وارد می‌شود؛ گذرواژهٔ فعلی لازم نیست.</div><div className="form-actions"><button type="button" className="secondary-button" onClick={() => setResetting(null)}>انصراف</button><button className="primary-button">بازنشانی گذرواژه</button></div></form></Modal>}
  </div>;
}

export function SettingsPage({ notify }: { notify: Notify }) {
  const [settings, setSettings] = useState<Record<string, string>>({}); const [shopName, setShopName] = useState(""); const [footer, setFooter] = useState(""); const [currency, setCurrency] = useState("AFN"); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const [backupPath, setBackupPath] = useState(""); const [passwords, setPasswords] = useState({ currentPassword: "", newPassword: "" });
  useEffect(() => { get<Record<string, string>>("/settings").then((data) => { setSettings(data); setShopName(data.shopName || ""); setFooter(data.receiptFooter || ""); setCurrency(data.currency || "AFN"); }).catch((e) => setError(e.message)); }, []);
  const saveSettings = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { await Promise.all([{ key: "shopName", value: shopName }, { key: "receiptFooter", value: footer }, { key: "currency", value: currency }].map((setting) => put("/settings", setting))); setSettings({ ...settings, shopName, receiptFooter: footer, currency }); notify("تنظیمات ذخیره شد."); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  const backup = async () => { setError(""); try { const result = await post<{ path: string }>("/settings/backup", {}); setBackupPath(result.path); notify("نسخه پشتیبان ساخته شد."); } catch (e) { setError((e as Error).message); } };
  const changePassword = async (event: FormEvent) => { event.preventDefault(); setError(""); try { await post("/auth/change-password", passwords); setPasswords({ currentPassword: "", newPassword: "" }); notify("گذرواژه تغییر کرد."); } catch (e) { setError((e as Error).message); } };
  return <div className="settings-grid"><div className="page-stack"><section className="surface"><SectionHead title="تنظیمات فروشگاه" subtitle="مشخصات روی فاکتور و صفحه اصلی"/><form className="form-grid single" onSubmit={saveSettings}><Field label="نام فروشگاه"><input required value={shopName} onChange={(e) => setShopName(e.target.value)}/></Field><Field label="ارز پایه"><select value={currency} onChange={(e) => setCurrency(e.target.value)}><option value="AFN">افغانی (AFN)</option></select></Field><Field label="پایین فاکتور"><textarea rows={3} value={footer} onChange={(e) => setFooter(e.target.value)}/></Field>{error && <div className="form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy ? "در حال ذخیره…" : "ذخیره تنظیمات"}</button></form></section>
      <section className="surface"><SectionHead title="تغییر گذرواژه" subtitle="گذرواژه پیش‌فرض را پس از ورود عوض کنید"/><form className="form-grid single" onSubmit={changePassword}><Field label="گذرواژه فعلی"><input type="password" required value={passwords.currentPassword} onChange={(e) => setPasswords({ ...passwords, currentPassword: e.target.value })} dir="ltr"/></Field><Field label="گذرواژه تازه (حداقل ۸ نویسه)"><input type="password" required minLength={8} value={passwords.newPassword} onChange={(e) => setPasswords({ ...passwords, newPassword: e.target.value })} dir="ltr"/></Field><button className="secondary-button">تغییر گذرواژه</button></form></section></div>
    <div className="page-stack"><section className="surface backup-card"><div className="backup-icon"><ShieldCheck size={22}/></div><span className="eyebrow">حفاظت از داده‌ها</span><h2>نسخه پشتیبان</h2><p>یک نسخه سالم از دیتابیس محلی بسازید. فایل پشتیبان در پوشه امن برنامه ذخیره می‌شود.</p><button className="primary-button" onClick={() => void backup()}><Archive size={17}/> ساخت نسخه پشتیبان</button>{backupPath && <div className="hint-box path-box">ذخیره شد:<br/><code dir="ltr">{backupPath}</code></div>}</section><section className="surface local-info"><div className="offline large-offline"><span/><div><b>ذخیره‌سازی محلی فعال است</b><small>پایگاه‌داده روی همین دستگاه قرار دارد.</small></div></div><div className="info-row"><span>حالت اجرا</span><b>تک‌کامپیوتر</b></div><div className="info-row"><span>دیتابیس</span><b>SQLite محلی</b></div><div className="info-row"><span>ارز تنظیم‌شده</span><b>{currency}</b></div></section></div></div>;
}
